def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    up = down = 0

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))

            cells = set(comp)
            # A T consists of a horizontal bar of three cells and one stem
            # attached above or below its center.
            for y, x in comp:
                if all((y, x+i) in cells for i in (-1, 0, 1)):
                    if (y-1, x) in cells:
                        up += 1
                    elif (y+1, x) in cells:
                        down += 1

    out = [[0] * 6 for _ in range(3)]
    up_slots = [(0,0), (0,2), (2,0), (2,2)]
    down_slots = [(0,3), (0,5), (2,3), (2,5)]
    for r, c in up_slots[:up]:
        out[r][c] = 3
    for r, c in down_slots[:down]:
        out[r][c] = 1
    return out
